//! Authenticated receive-source accounting before delivery de-duplication.
use crate::{
    format::Codec,
    media::{Mid, Pt},
};
use std::{
    collections::{BTreeSet, HashMap},
    sync::{
        Arc, Mutex,
        atomic::{AtomicU64, Ordering},
    },
    time::Instant,
};

/// Cumulative counters for one native receive-stream generation. Consuming a
/// snapshot never resets the source, replay state, or another receive stream.
#[derive(Clone, Debug)]
pub struct ReceiveTraffic {
    /// Stable identity, including when an SSRC or MID is reused later.
    pub source_id: u64,
    /// Negotiated media section owning primary and RTX traffic.
    pub mid: Mid,
    /// Primary SSRC; repaired traffic belongs to the same source.
    pub ssrc: u32,
    /// Time of the first authenticated real packet, not SDP creation.
    pub first_at: Option<Instant>,
    /// Codec of that first primary packet.
    pub codec: Option<Codec>,
    /// First packet is an RFC2198 RED carrier around the primary codec.
    pub red: bool,
    /// Original main payload type; RTX's transport payload type is excluded.
    pub payload_type: Option<Pt>,
    /// A later authenticated primary packet changed the receiver payload type.
    pub codec_changed: bool,
    /// Logical RTP bytes including authenticated duplicates, excluding RTX OSN.
    pub bytes: u64,
    /// Authenticated packets excluding synthetic RED recovery.
    pub packets: u64,
    /// Extended primary sequence-number span, including gaps, since source start.
    pub expected_packets: u64,
    /// Authenticated duplicate original sequence numbers, including repaired duplicates.
    pub duplicates: u64,
    /// Requested SNs generated by this receiver, before transport emission.
    pub nacks: u64,
    /// Final source snapshot; its owning logical receiver may still be alive.
    pub retired: bool,
    /// Stopped generation discarded by an automatic restart; no partial flush.
    pub discarded_on_restart: bool,
    /// Previous receive-source identity superseded by this detected restart.
    pub restarted_from: Option<u64>,
}
#[derive(Debug, Default)]
struct Pending {
    sources: HashMap<u64, ReceiveTraffic>,
    nacks: u64,
}
#[derive(Clone, Debug, Default)]
pub(crate) struct Registry(Arc<Mutex<Pending>>);
impl Registry {
    pub fn take(&self) -> Vec<ReceiveTraffic> {
        self.0
            .lock()
            .unwrap_or_else(|p| p.into_inner())
            .sources
            .drain()
            .map(|(_, v)| v)
            .collect()
    }
    pub fn generated_nacks(&self) -> u64 {
        self.0.lock().unwrap_or_else(|p| p.into_inner()).nacks
    }
}
static NEXT_SOURCE: AtomicU64 = AtomicU64::new(1);
#[derive(Clone, Copy, Debug)]
pub(crate) enum Admission {
    Rejected,
    Bypass,
    Accepted {
        flow: crate::receive_policy::Flow,
        duplicate: bool,
        restarted: bool,
    },
}
impl Admission {
    pub fn flow(self) -> Option<crate::receive_policy::Flow> {
        if let Self::Accepted { flow, .. } = self {
            Some(flow)
        } else {
            None
        }
    }
    pub fn restarted(self) -> bool {
        matches!(
            self,
            Self::Accepted {
                restarted: true,
                ..
            }
        )
    }
    pub fn rejected(self) -> bool {
        matches!(self, Self::Rejected)
    }
    pub fn duplicated(self) -> bool {
        matches!(
            self,
            Self::Accepted {
                duplicate: true,
                ..
            }
        )
    }
}
#[derive(Debug)]
pub(crate) struct Tracker {
    pub registry: Registry,
    value: ReceiveTraffic,
    highest_primary: Option<u64>,
    start_sequence: Option<u64>,
    seen: BTreeSet<u64>,
    policy: crate::receive_policy::Policy,
}
impl Tracker {
    pub fn new(mid: Mid, ssrc: u32, registry: Registry) -> Self {
        Self {
            registry,
            value: ReceiveTraffic {
                source_id: NEXT_SOURCE.fetch_add(1, Ordering::Relaxed),
                mid,
                ssrc,
                first_at: None,
                codec: None,
                red: false,
                payload_type: None,
                codec_changed: false,
                bytes: 0,
                packets: 0,
                expected_packets: 0,
                duplicates: 0,
                nacks: 0,
                retired: false,
                discarded_on_restart: false,
                restarted_from: None,
            },
            highest_primary: None,
            start_sequence: None,
            seen: BTreeSet::new(),
            policy: Default::default(),
        }
    }
    pub(crate) fn source_id(&self) -> u64 {
        self.value.source_id
    }
    pub(crate) fn is_started(&self) -> bool {
        self.value.first_at.is_some()
    }
    pub fn receive(
        &mut self,
        bytes: usize,
        codec: Codec,
        pt: Pt,
        repair: bool,
        red: bool,
        seq: u64,
        original_sequence: Option<u16>,
        has_media: bool,
        timestamp: u32,
        clock_rate: u32,
        restart_enabled: bool,
        now: Instant,
    ) -> Admission {
        let original = original_sequence.unwrap_or(seq as u16);
        if self.value.first_at.is_none() && repair {
            return Admission::Rejected;
        }
        let mut restarted = false;
        let flow = match self
            .policy
            .admit(original, timestamp, has_media, clock_rate, now)
        {
            Ok(flow) => flow,
            Err(crate::receive_policy::Rejected::Restart) if restart_enabled => {
                let old = self.value.source_id;
                self.value.retired = true;
                self.value.discarded_on_restart = true;
                self.publish();
                self.value.source_id = NEXT_SOURCE.fetch_add(1, Ordering::Relaxed);
                self.value.first_at = None;
                self.value.codec = None;
                self.value.payload_type = None;
                self.value.bytes = 0;
                self.value.packets = 0;
                self.value.expected_packets = 0;
                self.value.duplicates = 0;
                self.value.nacks = 0;
                self.value.codec_changed = false;
                self.value.retired = false;
                self.value.discarded_on_restart = false;
                self.value.restarted_from = Some(old);
                self.policy = Default::default();
                self.seen.clear();
                self.highest_primary = None;
                self.start_sequence = None;
                restarted = true;
                self.policy
                    .admit(original, timestamp, has_media, clock_rate, now)
                    .expect("detected restart replays its real media packet")
            }
            Err(_) => return Admission::Rejected,
        };
        let seq = flow.seq;
        if self.value.first_at.is_none() {
            // Fixed Buffer.calc rejects pre-start RTX; RTPStatsReceiver.Update
            // does not start on padding-only packets either.
            if !has_media {
                return Admission::Rejected;
            }
            self.start_sequence = Some(seq);
            self.value.first_at = Some(now);
            self.value.codec = Some(codec);
            self.value.red = red;
            self.value.payload_type = Some(pt);
        } else if !repair
            && has_media
            && codec.is_video()
            && flow.in_order
            && self.value.payload_type != Some(pt)
        {
            self.value.codec_changed = true;
        }
        let in_history = flow.in_order
            || self.highest_primary.is_none_or(|highest| {
                let distance = highest.wrapping_sub(seq) as i64;
                (0..8192).contains(&distance)
            });
        let duplicate = in_history && !self.seen.insert(seq);
        if duplicate {
            self.value.duplicates = self.value.duplicates.saturating_add(1);
        }
        if flow.in_order || self.highest_primary.is_none() {
            self.highest_primary = Some(seq);
            self.value.expected_packets = seq
                .wrapping_sub(self.start_sequence.unwrap())
                .wrapping_add(1);
            while self
                .seen
                .first()
                .is_some_and(|old| seq.wrapping_sub(*old) as i64 >= 8192)
            {
                self.seen.pop_first();
            }
            while self
                .seen
                .last()
                .is_some_and(|old| seq.wrapping_sub(*old) as i64 >= 8192)
            {
                self.seen.pop_last();
            }
        }
        self.value.bytes = self.value.bytes.saturating_add(bytes as u64);
        self.value.packets = self.value.packets.saturating_add(1);
        self.publish();
        Admission::Accepted {
            flow,
            duplicate,
            restarted,
        }
    }
    pub fn nack(&mut self, count: u64) {
        let mut pending = self.registry.0.lock().unwrap_or_else(|p| p.into_inner());
        pending.nacks = pending.nacks.saturating_add(count);
        if self.value.first_at.is_some() {
            self.value.nacks = self.value.nacks.saturating_add(count);
            pending
                .sources
                .insert(self.value.source_id, self.value.clone());
        }
    }
    fn publish(&self) {
        self.registry
            .0
            .lock()
            .unwrap_or_else(|p| p.into_inner())
            .sources
            .insert(self.value.source_id, self.value.clone());
    }
}
impl Drop for Tracker {
    fn drop(&mut self) {
        self.value.retired = true;
        self.publish();
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn initial_padding_and_rtx_do_not_start_then_original_sequence_span_and_repairs_account() {
        let registry = Registry::default();
        let mut tracker = Tracker::new(Mid::from("v"), 101, registry.clone());
        let now = Instant::now();
        let pt = Pt::from(98);
        tracker.receive(
            16,
            Codec::Vp9,
            pt,
            false,
            false,
            65000,
            None,
            false,
            3000,
            90000,
            false,
            now,
        );
        tracker.receive(
            20,
            Codec::Vp9,
            pt,
            true,
            false,
            9,
            Some(1),
            true,
            3000,
            90000,
            false,
            now,
        );
        tracker.nack(1);
        assert!(
            registry.take().is_empty(),
            "pre-start input must not publish a source"
        );
        assert_eq!(
            registry.generated_nacks(),
            1,
            "raw diagnostic does not invent a started source"
        );
        tracker.receive(
            20,
            Codec::Vp9,
            pt,
            false,
            false,
            100,
            None,
            true,
            3000,
            90000,
            false,
            now,
        );
        tracker.receive(
            20,
            Codec::Vp9,
            pt,
            false,
            false,
            102,
            None,
            true,
            3000,
            90000,
            false,
            now,
        );
        // Original sequence from RTX recovers the missing packet, not the
        // independent repair sequence 50000 (which would invent a huge gap).
        tracker.receive(
            20,
            Codec::Vp9,
            pt,
            true,
            false,
            50000,
            Some(101),
            true,
            3000,
            90000,
            false,
            now,
        );
        tracker.receive(
            20,
            Codec::Vp9,
            pt,
            true,
            false,
            50001,
            Some(101),
            true,
            3000,
            90000,
            false,
            now,
        );
        let row = registry.take().pop().unwrap();
        assert_eq!(
            (row.bytes, row.packets, row.expected_packets, row.duplicates),
            (80, 4, 3, 1)
        );
        assert_eq!(row.nacks, 0, "pre-start NACK cannot be resurrected");
        assert!(!row.codec_changed);
        tracker.receive(
            23,
            Codec::Vp8,
            Pt::from(96),
            false,
            false,
            102,
            None,
            true,
            3000,
            90000,
            false,
            now,
        );
        assert!(
            !registry.take().pop().unwrap().codec_changed,
            "equal-SN duplicate is out of order in original Go"
        );
        tracker.receive(
            23,
            Codec::Vp8,
            Pt::from(96),
            false,
            false,
            103,
            None,
            true,
            3000,
            90000,
            false,
            now,
        );
        assert!(registry.take().pop().unwrap().codec_changed);
    }
}
